CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, nom VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories (id BIGSERIAL PRIMARY KEY, nom VARCHAR(80) NOT NULL, type VARCHAR(10) NOT NULL CHECK(type IN ('revenu','depense')), user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(user_id,nom,type));
CREATE TABLE IF NOT EXISTS transactions (id BIGSERIAL PRIMARY KEY, libelle VARCHAR(160) NOT NULL, montant NUMERIC(14,2) NOT NULL CHECK(montant>0), type VARCHAR(10) NOT NULL CHECK(type IN ('revenu','depense')), description TEXT, date_operation DATE NOT NULL, categorie_id BIGINT NOT NULL REFERENCES categories(id) ON DELETE RESTRICT, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS budgets (id BIGSERIAL PRIMARY KEY, montant_limite NUMERIC(14,2) NOT NULL CHECK(montant_limite>0), mois SMALLINT NOT NULL CHECK(mois BETWEEN 1 AND 12), annee SMALLINT NOT NULL CHECK(annee BETWEEN 2000 AND 2200), categorie_id BIGINT REFERENCES categories(id) ON DELETE RESTRICT, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS budgets_scope_unique ON budgets(user_id,mois,annee,COALESCE(categorie_id,0));
CREATE TABLE IF NOT EXISTS objectifs_epargne (id BIGSERIAL PRIMARY KEY, nom VARCHAR(160) NOT NULL, description TEXT, montant_cible NUMERIC(14,2) NOT NULL CHECK(montant_cible>0), montant_initial NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK(montant_initial>=0), date_debut DATE NOT NULL, date_cible DATE NOT NULL CHECK(date_cible>=date_debut), statut VARCHAR(12) NOT NULL DEFAULT 'en_cours' CHECK(statut IN ('en_cours','atteint','annule')), user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS contributions_epargne (id BIGSERIAL PRIMARY KEY, montant NUMERIC(14,2) NOT NULL CHECK(montant>0), date_contribution DATE NOT NULL, objectif_id BIGINT NOT NULL REFERENCES objectifs_epargne(id) ON DELETE CASCADE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS transactions_user_date_idx ON transactions(user_id,date_operation DESC);
CREATE INDEX IF NOT EXISTS categories_user_idx ON categories(user_id);
CREATE INDEX IF NOT EXISTS goals_user_idx ON objectifs_epargne(user_id);
